package com.backend.nutri_predic.consumo.entity; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="detalles_evaluacion_consumo") public class DetalleEvaluacionConsumo { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="evaluacion_consumo_id") private EvaluacionConsumo evaluacion; private Long criterioEvaluadoId; @Column(length=100) private String componente; @Column(length=30) private String fuente; private BigDecimal cantidadObservada,referenciaAplicada,referenciaAplicadaHasta; @Column(length=30) private String unidad; @Column(length=30) private String operador; @Column(length=30) private String resultado; @Column(length=1000) private String motivoNoCalculable; public Long getId(){return id;} public EvaluacionConsumo getEvaluacion(){return evaluacion;} public Long getCriterioEvaluadoId(){return criterioEvaluadoId;} public String getComponente(){return componente;} public String getFuente(){return fuente;} public BigDecimal getCantidadObservada(){return cantidadObservada;} public BigDecimal getReferenciaAplicada(){return referenciaAplicada;} public BigDecimal getReferenciaAplicadaHasta(){return referenciaAplicadaHasta;} public String getUnidad(){return unidad;} public String getOperador(){return operador;} public String getResultado(){return resultado;} public String getMotivoNoCalculable(){return motivoNoCalculable;} public void setEvaluacion(EvaluacionConsumo v){evaluacion=v;} public void setCriterioEvaluadoId(Long v){criterioEvaluadoId=v;} public void setComponente(String v){componente=v;} public void setFuente(String v){fuente=v;} public void setCantidadObservada(BigDecimal v){cantidadObservada=v;} public void setReferenciaAplicada(BigDecimal v){referenciaAplicada=v;} public void setReferenciaAplicadaHasta(BigDecimal v){referenciaAplicadaHasta=v;} public void setUnidad(String v){unidad=v;} public void setOperador(String v){operador=v;} public void setResultado(String v){resultado=v;} public void setMotivoNoCalculable(String v){motivoNoCalculable=v;} }
